    M_Matrix = []; % Mass matrix
    M_Wing = [];   % Wing contribution to mass matrix
    M_Eng = [];    % Engine contribution to mass matrix

    for i = 1:n
        for j = 1:n
            Phi_I = (((y/L_W)^(i+1))*(2+i-i*(y/L_W)))/(i*(i+1)*(i+2));
            Phi_J = (((y/L_W)^(j+1))*(2+j-j*(y/L_W)))/(j*(j+1)*(j+2));
            Func_M = rho*A*Phi_I.*Phi_J;
            M_Wing(i,j) = int(Func_M,y,0,L_W);
            M_Eng(i,j) = M_E.*subs(Phi_I,L_E).*subs(Phi_J,L_E);
