mu = 500;          % Material density (kg/m^3)
rho = 1.225;       % Air density (kg/m^3)
c = 1;             % Airfoil chord length (m)
t = 0.01;          % Airfoil thickness (m)
l = 2;             % Length (m)
xf = 0.45;         % Distance of elastic axis from LE (m)
a = -0.05*c;       % Distance of elastic axis from mid-chord (m)
omega_h = 5*2*pi;  % Plunge natural freq (rad/s)
omega_a = 15*2*pi; % Pitch natural freq (rad/s)

b = c/2;               % Mid chord
m = mu*c*t;            % Mass per unit span (kg/m)
Ia = (m*c^2)/12+m*a^2; % Moment of inertia
Kh = m*omega_h^2;      % Plunge stiffness
Ka = Ia*omega_a^2;     % Pitch stiffness
U_Range = 0:0.1:80;    % Airspeed range

%{
---------------------------------------------------------------------------
P-K Method
---------------------------------------------------------------------------
%}

V1 = []; % Plunge natural frequency
d1 = []; % Plunge damping ratio
V2 = []; % Pitch natural frequency
d2 = []; % Pitch damping ratio

for U = U_Range
    elem = 3;
    for assumed_Freq = [sqrt(Kh/m) sqrt(Ka/Ia)]

        Error = 100;
        while Error > 0.1

            k = (assumed_Freq*b)/U;                              % Reduced frequency
            Ck = 1-0.165/(1-(0.0455/k)*1i)-0.335/(1-(0.3/k)*1i); % Theodorsen function

            D11 = -rho*pi*b^2;
            D12 = rho*pi*b^2*a;
            D21 = rho*pi*b^2*a;
            D22 = -rho*pi*b^2*(a^2+b^2/8);

            E11 = -2*rho*pi*b*U*Ck;
            E12 = -rho*pi*b^2*U + 2*rho*pi*b*U*Ck*(a-b/2);
            E21 = rho*pi*b^2*U - rho*pi*b*U*(b-(2*a+b)*Ck);
            E22 = rho*pi*b*U*(b-(2*a+b)*Ck)*(a-b/2);

            F11 = 0;
            F12 = -2*rho*pi*b*U^2*Ck;
            F21 = 0;
            F22 = rho*pi*b^2*U^2 - rho*pi*b*U^2*(b-(2*a+b)*Ck);

            M = [m -m*a; -m*a Ia];  % Mass matrix
            K = [Kh 0; 0 Ka];       % Stiffness matrix
            D = [D11 D12; D21 D22]; % 2nd order matrix
            E = [E11 E12; E21 E22]; % 1st order matrix
            F = [F11 F12; F21 F22]; % Constants matrix
            A = [[0 0; 0 0] [1 0; 0 1]; (inv(M-D))*(F-K) (inv(M-D))*E]; % Assembled matrix

            d = eig(A);                              % Solve for eigenvalues
            [d_imag,index] = sort(imag(d),"ascend"); % Sort eigenvalues by imaginary part
            calc_Freq = d_imag(elem);                % Store calculated heave/pitch frequency
            Error = abs(calc_Freq-assumed_Freq);     % Calculate error between calculated vs assumed
            assumed_Freq = calc_Freq;                % Update assumed frequency if error is bigger than 0.1

        end

        d_Sorted = d(index);
        if elem==3; V1 = [V1; abs(d_Sorted(elem))]; d1 = [d1; -real(d_Sorted(elem))/abs(d_Sorted(elem))]; end % Store converged freq & damping ratio (Plunge)
        if elem==4; V2 = [V2; abs(d_Sorted(elem))]; d2 = [d2; -real(d_Sorted(elem))/abs(d_Sorted(elem))]; end % Store converged freq & damping ratio (Pitch)
        elem = elem+1;

    end
end

