clear; clc;

mu = 500;          % Material density (kg/m^3)
rho = 1.225;       % Air density (kg/m^3)
c = 1;             % Airfoil chord length (m)
t = 0.01;          % Airfoil thickness (m)
l = 2;             % Length (m)
xf = 0.45*c;       % Distance of elastic axis from LE (m)
a = -0.05*c;       % Distance of elastic axis from nid-chord (m)
omega_h = 5*2*pi;  % Plunge natural freq (Hz)
omega_a = 15*2*pi; % Pitch natural freq (Hz)

b = c/2;               % Mid chord
m = mu*c*t;            % Mass per unit span (kg/m)
Ia = (m*c^2)/12+m*a^2; % Moment of inertia
Kh = m*omega_h^2;      % Plunge stiffness
Ka = Ia*omega_a^2;     % Pitch stiffness
U_Range = 0:0.1:80;    % Airspeed range

%{
---------------------------------------------------------------------------
Wagner's Function
---------------------------------------------------------------------------
%}

syms t;         % Time
e = xf/c-0.25;  % Distance between ac & elastic axis
eVal = [];      % Eigenvalues
N_Freq = [];    % Natural frequencies (Plunge & Pitch)
D_Ratio = [];   % Damping ratios (Plunge & Pitch)
Q = zeros(8,8); % Assembled matrix
Psi1 = 0.165;   % Wagner's function coefficient 1
Psi2 = 0.335;   % Wagner's function coefficient 2
eps1 = 0.0455;  % Wagner's function exponential 1
eps2 = 0.3;     % Wagner's function exponential 2

for U = U_Range

    Phi = 1-Psi1*exp(-eps1*U*t/b)-Psi2*exp(-eps2*U*t/b); % Wagner's function
    Phi_d = diff(Phi,t);                                 % Differentiate Wagner's function
    Phi = subs(Phi,t,0);                                 % Substitute t=0 into Phi
    Phi_d = subs(Phi_d,t,0);                             % Substitute t=0 into Phi dot

    M11 = m + rho*pi*b^2;
    M12 = -m*a - rho*pi*b^2*(xf-c/2);
    M21 = -m*a - rho*pi*b^2*(xf-c/2);
    M22 = Ia + rho*pi*b^2*((xf-c/2)^2+b^2/8);

    C11 = Phi;
    C12 = c/4 + Phi*(3*c/4-xf);
    C21 = -e*c*Phi;
    C22 = (3*c/4-xf)*(c/4-e*c*Phi);

    K11 = Kh + rho*pi*U*c*Phi_d;
    K12 = rho*pi*U*c*(U*Phi + (3*c/4-xf)*Phi_d);
    K21 = -rho*pi*U*e*c^2*Phi_d;
    K22 = Ka - rho*pi*U*e*c^2*(U*Phi + (3*c/4-xf)*Phi_d);

    W11 = -Psi1*eps1^2/b;
    W12 = -Psi2*eps2^2/b;
    W13 = Psi1*eps1*(1-eps1*(1-2*e));
    W14 = Psi2*eps2*(1-eps2*(1-2*e));
    W21 = e*c*Psi1*eps1^2/b;
    W22 = e*c*Psi2*eps2^2/b;
    W23 = -e*c*Psi1*eps1*(1-eps1*(1-2*e));
    W24 = -e*c*Psi2*eps2*(1-eps2*(1-2*e));

    M = [M11 M12; M21 M22];            % 2nd order matrix
    C = rho*pi*U*c*[C11 C12; C21 C22]; % 1st order matrix
    K = [K11 K12; K21 K22];            % Constants matrix
    W = 2*rho*pi*U^3*[W11 W12 W13 W14; W21 W22 W23 W24];
    B = [1 0; 1 0; 0 1; 0 1];
    G = [-eps1*U/b 0 0 0; 0 -eps2*U/b 0 0; 0 0 -eps1*U/b 0; 0 0 0 -eps2*U/b];

    Q(1:2, 1:2) = -(inv(M))*C;
    Q(1:2, 3:4) = -(inv(M))*K;
    Q(1:2, 5:8) = -(inv(M))*W;
    Q(3:4, 1:2) = eye(2);
    Q(5:8, 3:4) = B;
    Q(5:8, 5:8) = G;

    d = eig(Q);
    [d_imag,index] = sort(imag(d),"ascend"); % Sort eigenvalues by imaginary part
    d_Sorted = d(index);
    eVal = [eVal; d_Sorted(7) d_Sorted(8)]; % Store eigenvalues for plunge & pitch

end

%{
---------------------------------------------------------------------------
Natural Frequencies & Damping Ratios vs Airspeed
---------------------------------------------------------------------------
%}

eps = 1e-6;
Found = false;
for elem = 1:1:size(U_Range,2)

    N_Freq(elem,1) = abs(eVal(elem,1));
    N_Freq(elem,2) = abs(eVal(elem,2));
    D_Ratio(elem,1) = -real(eVal(elem,1))/abs(eVal(elem,1));
    D_Ratio(elem,2) = -real(eVal(elem,2))/abs(eVal(elem,2));

    if D_Ratio(elem,1)<0 && abs(D_Ratio(elem,1))>eps && ~Found
        U_Flutter = U_Range(elem);
        Freq_Flutter = N_Freq(elem,1)/2/pi;
        Found = true;
    end

    if D_Ratio(elem,2)<0 && abs(D_Ratio(elem,1))>eps && ~Found
        U_Flutter = U_Range(elem);
        Freq_Flutter = N_Freq(elem,2)/2/pi;
        Found = true;
    end

end

fprintf("Flutter Speed (Wagner) : %.2f m/s \n", U_Flutter);
fprintf("Flutter Frequency (Wagner) : %.3f Hz \n", Freq_Flutter);

figure(1)
title("Natural Frequency vs Airspeed")
xlabel("U (m/s)")
ylabel("Natural Frequency (Hz)")
